const userHasEncryptedContent = `-- name: UserHasEncryptedContent :one
SELECT (
    EXISTS (SELECT 1 FROM goal_versions WHERE user_id = $1::uuid AND content_storage_format = 'encrypted-v1')
    OR EXISTS (SELECT 1 FROM goal_drafts WHERE user_id = $1::uuid AND content_storage_format = 'encrypted-v1')
    OR EXISTS (
      SELECT 1 FROM goal_version_success_signals signal
      JOIN goal_versions version ON version.id = signal.goal_version_id
      WHERE version.user_id = $1::uuid AND signal.content_storage_format = 'encrypted-v1'
    )
    OR EXISTS (
      SELECT 1 FROM goal_draft_success_signals signal
      JOIN goal_drafts draft ON draft.id = signal.goal_draft_id
      WHERE draft.user_id = $1::uuid AND signal.content_storage_format = 'encrypted-v1'
    )
    OR EXISTS (SELECT 1 FROM pdca_cycles WHERE user_id = $1::uuid AND content_storage_format = 'encrypted-v1')
    OR EXISTS (SELECT 1 FROM ai_generations WHERE user_id = $1::uuid AND content_storage_format = 'encrypted-v1')
)::boolean AS has_encrypted_content
`

func (q *Queries) UserHasEncryptedContent(ctx context.Context, userID pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, userHasEncryptedContent, userID)
	var has_encrypted_content bool
	err := row.Scan(&has_encrypted_content)
	return has_encrypted_content, err
}
